'use strict';
let profile=null,csrf='',bootstrap={},currentView='feed',videos=[];
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message,bad=false){const t=$('#toast');t.textContent=message;t.className='toast'+(bad?' bad':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.add('hidden'),4500)}
async function request(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});const value=await r.json();if(r.status===401&&path!=='/api/login'){profile=null;csrf='';$('#workspace').classList.add('hidden');$('#login').classList.remove('hidden');$('#login-error').textContent='Your session expired. Please sign in again.';}if(!r.ok)throw Error(value.error||'Request failed');return value}
const api=async(action,payload={})=>(await request('/api/action',{action,payload})).data;
async function showWorkspace(){bootstrap=await api('bootstrap');$('#login').classList.add('hidden');$('#workspace').classList.remove('hidden');$('#profile').textContent=profile.nickname;$('#reports-nav').classList.toggle('hidden',profile.user_id!==1);await view('feed')}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('#login-error').textContent='';try{const r=await request('/api/login',Object.fromEntries(new FormData(e.target)));profile=r.profile;csrf=r.csrf;await showWorkspace()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}});
$('#logout').onclick=async()=>{await request('/api/logout',{});location.reload()};
document.querySelector('nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)view(b.dataset.view).catch(err=>toast(err.message,true))};
async function view(name){currentView=name;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#page-title').textContent=({feed:'Explore your community',publish:'Share a small moment',collections:'Your saved discoveries',reports:'From SQL to insight'})[name];$('#main').innerHTML='<p class="empty">Loading from PostgreSQL…</p>';if(name==='feed')await feed();if(name==='publish')publish();if(name==='collections')await collections();if(name==='reports')reports()}
async function feed(search=''){videos=await api('feed',{search});$('#main').innerHTML=`<div class="toolbar"><div><h2>Fresh perspectives</h2><span class="section-note">${videos.length} available videos · Yours remain visible when hidden</span></div><form id="search"><input name="search" value="${esc(search)}" placeholder="Search video captions…" aria-label="Search video captions"></form></div><div class="grid">${videos.map(v=>`<article class="card"><video controls preload="metadata" muted src="/media/demo.webm"></video><div class="card-body"><div class="meta"><span>${esc(v.duration_seconds)}s</span><span class="badge">${esc(v.visibility_status)}</span></div><h3>${esc(v.caption)||'An untitled moment'}</h3><div class="creator"><span class="avatar">${esc(v.nickname.slice(-1))}</span>${esc(v.nickname)}${v.is_mine?' · You':''}</div><div class="actions"><button data-action="${v.liked?'unlike':'like'}" data-id="${v.video_id}" class="${v.liked?'selected':''}">♡ ${v.like_count}</button><button data-action="comments" data-id="${v.video_id}">Comments</button><button data-action="save" data-id="${v.video_id}">Save</button>${v.is_mine?`<button data-action="edit" data-id="${v.video_id}">Edit</button><button data-action="${v.visibility_status==='HIDDEN'?'unhide':'hide'}" data-id="${v.video_id}">${v.visibility_status==='HIDDEN'?'Publish again':'Hide'}</button><button data-action="tag" data-id="${v.video_id}">Topic</button>`:`<button data-action="${v.following?'unfollow':'follow'}" data-user="${v.creator_id}">${v.following?'Following':'Follow'}</button>`}</div></div></article>`).join('')}</div>`;$('#search').onsubmit=e=>{e.preventDefault();feed(new FormData(e.target).get('search')).catch(err=>toast(err.message,true))}}
function openDialog(content){$('#dialog-content').innerHTML=content;if(!$('#dialog').open)$('#dialog').showModal()}
async function comments(id){const rows=await api('comments',{video_id:id});openDialog(`<h2>Conversation</h2><p class="muted small">Video #${id} · hidden replies retain a redacted anchor.</p><div>${rows.map(r=>`<div class="comment d${Math.min(r.depth,3)}"><small class="muted">#${r.comment_id} · ${r.author_id?'User '+r.author_id:'Hidden author'}</small><div>${esc(r.body_text)}</div><button data-action="reply" data-id="${r.comment_id}">Reply to #${r.comment_id}</button></div>`).join('')||'<p class="empty">Start the conversation.</p>'}</div><form id="comment-form"><input name="video_id" type="hidden" value="${id}"><label>Reply to<input name="parent_comment_id" placeholder="Leave empty for a new thread" type="number" min="1"></label><label>Your comment<textarea name="body_text" required placeholder="Add something thoughtful…"></textarea></label><button class="primary">Post comment</button></form>`);$('#comment-form').onsubmit=async e=>{e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));if(!d.parent_comment_id)delete d.parent_comment_id;await api('comment',d);toast('Comment saved in PostgreSQL');await comments(id)}catch(err){toast(err.message,true)}}}
function publish(){const music=(bootstrap.music||[]).map(m=>`<option value="${m.music_id}">${esc(m.title)}</option>`).join('');$('#main').innerHTML=`<section class="form-panel"><h2>Publish a video</h2><p class="muted">Create a real database record with a generated video ID.</p><form id="publish-form"><label>Caption<textarea name="caption" placeholder="What is this moment about?"></textarea></label><div class="form-row"><label>Duration in seconds<input type="number" name="duration_seconds" min="0.001" step="0.001" value="3.000" required></label><label>Music<select name="music_id"><option value="">No music</option>${music}</select></label></div><label>Media location<input name="media_url" value="/media/demo.webm" required></label><p class="small muted">The bundled clip is an original generated demo animation. Media bytes stay outside the relational database.</p><button class="primary">Publish video →</button></form></section>`;$('#publish-form').onsubmit=async e=>{e.preventDefault();try{const p=Object.fromEntries(new FormData(e.target));if(!p.music_id)delete p.music_id;const r=await api('publish',p);toast('Published video #'+r.video_id);await view('feed')}catch(err){toast(err.message,true)}}}
async function collections(){const rows=await api('collections');$('#main').innerHTML=`<div class="toolbar"><div><h2>Keep the good ones</h2><span class="section-note">Your collections are private to your database identity.</span></div><button data-action="new-collection" class="primary">＋ New collection</button></div>${rows.map(c=>`<section class="collection"><h3>${esc(c.name)}</h3><p class="small muted">Collection #${c.collection_id} · ${c.items.length} published videos</p><ul>${c.items.map(i=>`<li><span>#${i.item_no} · ${esc(i.caption)||'Untitled video'}</span><button data-action="remove-item" data-id="${c.collection_id}" data-item="${i.item_no}">Remove</button></li>`).join('')||'<li class="muted">No published videos saved yet.</li>'}</ul></section>`).join('')}`}
const REPORTS=['Creator videos','Topic search','Per-video likes','Comment tree','Followers and following','Mutual follows','Collection contents','Most-liked videos','Active creators','Popular topics'];
function reports(){$('#main').innerHTML=`<h2>Ten questions. Ten queries.</h2><p class="muted">Run the submitted SELECT statements against the live database.</p><form id="report-form" class="report-controls"><select name="id">${REPORTS.map((r,i)=>`<option value="Q${String(i+1).padStart(2,'0')}">Q${String(i+1).padStart(2,'0')} · ${r}</option>`).join('')}</select><button class="primary">Run query</button></form><div id="report-output"></div>`;$('#report-form').onsubmit=async e=>{e.preventDefault();try{const id=new FormData(e.target).get('id');const rows=await api('report',{id});const keys=Object.keys(rows[0]||{});$('#report-output').innerHTML=`<p class="small muted">${esc(id)} · ${rows.length} rows returned from PostgreSQL</p><div class="table-wrap"><table><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${r[k]===null?'NULL':esc(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}catch(err){toast(err.message,true)}}}
document.body.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;const id=Number(b.dataset.id);try{b.disabled=true;if(action==='comments'){await comments(id);return}if(action==='reply'){$('#comment-form [name="parent_comment_id"]').value=id;$('#comment-form textarea').focus();return}if(action==='save'){const cs=await api('collections');openDialog(`<h2>Save to a collection</h2><form id="save-form"><label>Collection<select name="collection_id">${cs.map(c=>`<option value="${c.collection_id}">${esc(c.name)}</option>`).join('')}</select></label><button class="primary" ${cs.length?'':'disabled'}>Save video</button></form><p class="small muted">Create a collection first if none are available.</p>`);$('#save-form').onsubmit=async e=>{e.preventDefault();try{const cid=Number(new FormData(e.target).get('collection_id'));const r=await api('collect',{collection_id:cid,video_id:id});toast(r.already_present?'Already saved':'Saved as item #'+r.item_no);$('#dialog').close()}catch(err){toast(err.message,true)}};return}if(action==='new-collection'){openDialog('<h2>New collection</h2><form id="new-collection-form"><label>Name<input name="name" required maxlength="100"></label><button class="primary">Create collection</button></form>');$('#new-collection-form').onsubmit=async e=>{e.preventDefault();try{await api('create_collection',Object.fromEntries(new FormData(e.target)));$('#dialog').close();await collections();toast('Collection created')}catch(err){toast(err.message,true)}};return}if(action==='edit'){const v=videos.find(v=>v.video_id===id);openDialog(`<h2>Edit your video</h2><form id="edit-form"><label>Caption<textarea name="caption">${esc(v.caption)}</textarea></label><button class="primary">Save changes</button></form>`);$('#edit-form').onsubmit=async e=>{e.preventDefault();try{await api('edit',{video_id:id,...Object.fromEntries(new FormData(e.target))});$('#dialog').close();await feed();toast('Caption updated')}catch(err){toast(err.message,true)}};return}if(action==='tag'){openDialog(`<h2>Add a topic</h2><form id="topic-form"><label>Topic<select name="topic_id">${bootstrap.topics.map(t=>`<option value="${t.topic_id}">${esc(t.topic_name)}</option>`).join('')}</select></label><button class="primary">Attach topic</button></form>`);$('#topic-form').onsubmit=async e=>{e.preventDefault();try{await api('tag',{video_id:id,topic_id:Number(new FormData(e.target).get('topic_id'))});$('#dialog').close();toast('Topic attached')}catch(err){toast(err.message,true)}};return}if(action==='remove-item'){await api('remove_collection_item',{collection_id:id,item_no:Number(b.dataset.item)});await collections();toast('Removed from your collection');return}await api(action,action==='follow'||action==='unfollow'?{target_user_id:Number(b.dataset.user)}:{video_id:id});toast('Database updated');await feed()}catch(err){toast(err.message,true)}finally{b.disabled=false}});
fetch('/api/session').then(r=>r.json()).then(async s=>{if(s.profile){profile=s.profile;csrf=s.csrf;await showWorkspace()}}).catch(err=>toast(err.message,true));
